#!/usr/bin/env Rscript
# Generate src/ztp_tz_links.c, the table of IANA link identifiers and their
# targets, from the `backward` file of the tzdata release named in
# inst/spec/PINS (design 8.3). Base R only. Run from the package root:
#
#   Rscript tools/tz/links.R
#
# The release tarball is downloaded to a temporary directory and its SHA-256
# is recorded in the generated file; the output is deterministic for a
# given release.

pins <- read.dcf("inst/spec/PINS")
version <- pins[1L, "Tzdata"]
url <- sprintf("https://data.iana.org/time-zones/releases/tzdata%s.tar.gz", version)
dir <- tempfile("tzdata")
dir.create(dir)
tarball <- file.path(dir, basename(url))
download.file(url, tarball, mode = "wb", quiet = TRUE)
sha <- tools::sha256sum(tarball)
untar(tarball, exdir = dir)
found <- trimws(readLines(file.path(dir, "version"), warn = FALSE))
found <- found[nzchar(found)][1L]
if (found != version) {
  stop(sprintf("the tarball says tzdata %s, inst/spec/PINS says %s", found, version))
}

lines <- readLines(file.path(dir, "backward"), warn = FALSE)
lines <- sub("#.*$", "", lines)
links <- lines[grepl("^Link[[:space:]]", lines)]
fields <- strsplit(trimws(links), "[[:space:]]+")
target <- vapply(fields, `[[`, "", 2L)
link <- vapply(fields, `[[`, "", 3L)
stopifnot(!anyDuplicated(link), all(nzchar(target)), all(nzchar(link)))
# Resolve chains (a link to a link) so that every entry names a primary.
repeat {
  idx <- match(target, link)
  if (all(is.na(idx))) break
  target[!is.na(idx)] <- target[idx[!is.na(idx)]]
}
ord <- order(tolower(link), method = "radix")
link <- link[ord]
target <- target[ord]

c_string <- function(x) paste0("\"", gsub("([\\\\\"])", "\\\\\\1", x), "\"")
body <- sprintf("    {%s, %s},", c_string(link), c_string(target))
out <- c(
  "/*",
  " * ztp_tz_links.c -- IANA link identifiers and their primary targets",
  " * (design 8.3). Generated by tools/tz/links.R from the `backward` file of",
  sprintf(" * tzdata %s (SHA-256 %s); do not edit.", version, sha),
  " *",
  " * Sorted by the ASCII-case-folded link, for binary search. A chain of",
  " * links is resolved, so every target is a primary identifier.",
  " */",
  "",
  "#include \"ztp_tz.h\"",
  "",
  sprintf("const char *const ztp_tz_links_version = \"%s\";", version),
  "",
  "const ztp_tz_link ztp_tz_links[] = {",
  body,
  "};",
  "",
  sprintf("const size_t ztp_tz_links_count = %d;", length(link)),
  ""
)
writeLines(out, "src/ztp_tz_links.c")
cat(sprintf("%d links from tzdata %s written to src/ztp_tz_links.c\n", length(link), version))
